import{_ as e,c as a,a0 as d,o as r}from"./chunks/framework.B6JXc2q-.js";const m=JSON.parse('{"title":"固定请求身份的认证观察","description":"","frontmatter":{},"headers":[],"relativePath":"maintenance/2026-11-10-pass-token-identity-freeze-observation.md","filePath":"maintenance/2026-11-10-pass-token-identity-freeze-observation.md"}'),o={name:"maintenance/2026-11-10-pass-token-identity-freeze-observation.md"};function i(n,t,s,c,h,l){return r(),a("div",null,t[0]||(t[0]=[d('<h1 id="固定请求身份的认证观察" tabindex="-1">固定请求身份的认证观察 <a class="header-anchor" href="#固定请求身份的认证观察" aria-label="Permalink to &quot;固定请求身份的认证观察&quot;">​</a></h1><p>首次记录：2026-11-10。收尾核查：2026-11-22（日本时间）。 对象：测试环境，候选镜像 <code>xiaomusic-core:auth-identity-warning-20261106</code>。</p><h2 id="观察结果" tabindex="-1">观察结果 <a class="header-anchor" href="#观察结果" aria-label="Permalink to &quot;观察结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>结果</th></tr></thead><tbody><tr><td>本轮扫码</td><td>2026-11-06 12:41 JST</td></tr><tr><td>11月10日检查</td><td>约105小时，认证可用</td></tr><tr><td>11月22日检查</td><td>约15天20小时，同一轮凭据仍可用</td></tr><tr><td>计划续期</td><td>31次触发、31次换票观测、31次验证后CAS提交，逐次对应</td></tr><tr><td>最后成功提交</td><td>2026-11-22 02:20:29 JST</td></tr><tr><td>长期凭据轮换</td><td>31次观测均未轮换，取得时间未重置</td></tr><tr><td>容器</td><td>同一候选镜像，重启计数0</td></tr><tr><td>拒绝/验证码/续期暂停</td><td>本轮容器日志未发现对应事件</td></tr></tbody></table><p>证据来源：维护者只读查询容器状态、状态API、持久化时间元数据及扫码后的完整容器日志，并核对提交代码先验证后CAS的顺序。磁盘 <code>xiaomusic.log.txt</code> 仅有启动记录，本次续期统计使用 <code>docker logs</code>。统计不含凭据值、指纹、长度、账号或响应原文。</p><h2 id="与旧周期的比较" tabindex="-1">与旧周期的比较 <a class="header-anchor" href="#与旧周期的比较" aria-label="Permalink to &quot;与旧周期的比较&quot;">​</a></h2><p>旧周期在约72小时仍能续期，约84小时首次被拒。本轮超过该窗口后仍持续续期成功。旧周期详见 <code>2026-10-24-auth-pass-token-lifecycle-experiment.md</code>。</p><p>依赖 miservice-fork 2.9.3 的旧路径每次 <code>_serviceLogin</code> 随机生成 UA，STS 默认请求也未显式沿用扫码 UA。本轮通过账号独立 session 绑定已保存 UA，并保留 deviceId，统一扫码、续期及换取短会话的身份。刷新间隔仍为12小时，没有引入密码登录。</p><p>结果支持身份一致性修复有效。没有服务端风控判定、随机对照或多账号样本，无法证明唯一根因；同期服务端策略或账号状态变化尚不能排除。旧记录中的“决定性对照”“固定硬限”“已排除风控”等表述不再沿用。</p><h2 id="保活警告" tabindex="-1">保活警告 <a class="header-anchor" href="#保活警告" aria-label="Permalink to &quot;保活警告&quot;">​</a></h2><p>扫码后日志包含75条保活不健康警告和25条退化恢复记录。源码核查发现：成功轮次只有在已经退化时才重置连续失败计数，可将间歇失败累计到阈值。这解释了计数可能失真的机制，但不能证明每次探测失败的具体原因。</p><p>v1.1.8 修正成功轮次归零，增加实际探测、门禁、失败类别及累计计数。单次探测失败原因仍待新诊断数据验证，不预先归为网络波动。</p><h2 id="收尾决定" tabindex="-1">收尾决定 <a class="header-anchor" href="#收尾决定" aria-label="Permalink to &quot;收尾决定&quot;">​</a></h2><p>保留身份一致性方案；移除60小时到期风险提示，年龄仅作信息展示；保留真实续期挂起警告。观察结论针对已运行的候选镜像，v1.1.8 新增的计数与显示修复尚未在服务器部署。</p>',14)]))}const b=e(o,[["render",i]]);export{m as __pageData,b as default};
